def split_words(text: str) -> list[str]:
    delimiters = (' ', '\t', '\n')
    double_escapes = {'"', '\\', '$', '`'}

    n = len(text)
    words = []
    parts = []
    started = False
    i = 0

    while i < n:
        c = text[i]

        if c == ' ' or c == '\t' or c == '\n':
            if started:
                words.append(''.join(parts))
                parts.clear()
                started = False
            i += 1
            continue

        if c == '#':
            if not started:
                while i < n and text[i] != '\n':
                    i += 1
                continue
            parts.append(c)
            started = True
            i += 1
            continue

        if c == "'":
            started = True
            i += 1
            if i == n:
                raise ValueError("unterminated single quote")

            start = i
            while i < n and text[i] != "'":
                i += 1

            if i == n:
                raise ValueError("unterminated single quote")

            if i > start:
                parts.extend(text[start:i])

            i += 1
            continue

        if c == '"':
            started = True
            i += 1
            if i == n:
                raise ValueError("unterminated double quote")

            closed = False
            while i < n:
                c = text[i]

                if c == '"':
                    closed = True
                    i += 1
                    break

                if c == '\\':
                    if i + 1 == n:
                        raise ValueError("trailing backslash in double quote")

                    nxt = text[i + 1]

                    if nxt == '\n':
                        i += 2
                        continue

                    if nxt in double_escapes:
                        parts.append(nxt)
                        i += 2
                    else:
                        parts.append('\\')
                        i += 1

                    continue

                parts.append(c)
                i += 1

            if not closed:
                raise ValueError("unterminated double quote")

            continue

        if c == '\\':
            if i + 1 == n:
                raise ValueError("trailing backslash")

            nxt = text[i + 1]

            if nxt == '\n':
                i += 2
                continue

            parts.append(nxt)
            started = True
            i += 2
            continue

        parts.append(c)
        started = True
        i += 1

    if started:
        words.append(''.join(parts))

    return words
